#include <stdio.h>
#define MAX 20

int main(void) {
    int n, i, t = 0, done = 0;
    int at[MAX], bt[MAX], ct[MAX], finished[MAX] = {0};
    double sumTat = 0, sumWt = 0;

    printf("Number of processes: ");
    if (scanf("%d", &n) != 1 || n < 1 || n > MAX) return 1;
    for (i = 0; i < n; i++) {
        printf("Arrival and burst of P%d: ", i + 1);
        if (scanf("%d %d", &at[i], &bt[i]) != 2) return 1;
    }

    while (done < n) {
        int pick = -1;
        /* among the arrived, unfinished processes pick the shortest burst;
           a tie goes to the earlier arrival, then the lower index */
        for (i = 0; i < n; i++) {
            if (finished[i] || at[i] > t) continue;
            if (pick == -1 || bt[i] < bt[pick] ||
                (bt[i] == bt[pick] && at[i] < at[pick]))
                pick = i;
        }
        if (pick == -1) {            /* CPU idle: jump to the next arrival */
            int next = -1;
            for (i = 0; i < n; i++)
                if (!finished[i] && (next == -1 || at[i] < next)) next = at[i];
            t = next;
            continue;
        }
        printf("| P%d %d-%d ", pick + 1, t, t + bt[pick]);
        t += bt[pick];               /* non-preemptive: runs to completion */
        ct[pick] = t;
        finished[pick] = 1;
        done++;
    }
    printf("|\n\nProcess  AT  BT  CT  TAT  WT\n");
    for (i = 0; i < n; i++) {
        int tat = ct[i] - at[i], wt = tat - bt[i];
        sumTat += tat;
        sumWt += wt;
        printf("P%-7d %-3d %-3d %-3d %-4d %d\n", i + 1, at[i], bt[i], ct[i], tat, wt);
    }
    printf("Average TAT = %.2f, Average WT = %.2f\n", sumTat / n, sumWt / n);
    return 0;
}

