#include <stdio.h>
#define MAX 20
#define QSIZE 1000

int main(void) {
    int n, q, i, t = 0, next = 0, done = 0;
    int at[MAX], bt[MAX], rem[MAX], ct[MAX], first[MAX];
    int queue[QSIZE], head = 0, tail = 0;
    double sumTat = 0, sumWt = 0, sumRt = 0;

    printf("Number of processes and time quantum: ");
    if (scanf("%d %d", &n, &q) != 2 || n < 1 || n > MAX || q < 1) return 1;
    printf("Arrival and burst of each process, sorted by arrival:\n");
    for (i = 0; i < n; i++) {
        if (scanf("%d %d", &at[i], &bt[i]) != 2) return 1;
        rem[i] = bt[i];
        first[i] = -1;
    }

    while (done < n) {
        while (next < n && at[next] <= t) queue[tail++] = next++;  /* admit arrivals */
        if (head == tail) { t = at[next]; continue; }              /* CPU idle */
        int p = queue[head++];
        int run = rem[p] < q ? rem[p] : q;
        if (first[p] == -1) first[p] = t;
        printf("| P%d %d-%d ", p + 1, t, t + run);
        t += run;
        rem[p] -= run;
        /* processes that arrived during this slice join before the preempted one */
        while (next < n && at[next] <= t) queue[tail++] = next++;
        if (rem[p] > 0) queue[tail++] = p;
        else { ct[p] = t; done++; }
    }
    printf("|\n\nProcess  CT  TAT  WT  RT\n");
    for (i = 0; i < n; i++) {
        int tat = ct[i] - at[i], wt = tat - bt[i], rt = first[i] - at[i];
        sumTat += tat; sumWt += wt; sumRt += rt;
        printf("P%-7d %-3d %-4d %-3d %d\n", i + 1, ct[i], tat, wt, rt);
    }
    printf("Average TAT = %.2f, WT = %.2f, RT = %.2f\n", sumTat / n, sumWt / n, sumRt / n);
    return 0;
}

