#include <stdio.h>
#include <pthread.h>

#define DEPOSITS 100000          /* each teller thread deposits Tk 1 this many times */

long balance = 0;                /* shared account balance */
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
int useLock;

void *teller(void *arg) {
    (void)arg;
    for (int i = 0; i < DEPOSITS; i++) {
        if (useLock) pthread_mutex_lock(&lock);
        long b = balance;        /* read   */
        b = b + 1;               /* modify */
        balance = b;             /* write: the critical section ends here */
        if (useLock) pthread_mutex_unlock(&lock);
    }
    return NULL;
}

long run(int withLock) {
    pthread_t t1, t2;
    balance = 0;
    useLock = withLock;
    pthread_create(&t1, NULL, teller, NULL);
    pthread_create(&t2, NULL, teller, NULL);
    pthread_join(t1, NULL);
    pthread_join(t2, NULL);
    return balance;
}

int main(void) {
    printf("Expected balance: %d\n", 2 * DEPOSITS);
    printf("Without mutex   : %ld\n", run(0));
    printf("With mutex      : %ld\n", run(1));
    return 0;
}

Sample output (compile with -lpthread; the unlocked value changes from run to run):
Expected balance: 200000
Without mutex   : 119089
With mutex      : 200000

Why: balance = balance + 1 is a read, an add and a write. When both threads read the same old value before either writes, one deposit is lost (a lost update), so the unlocked total is usually below 200000; on some runs it may happen to be correct, which is what makes races hard to find. The mutex turns read-modify-write into a critical section, so exactly one thread updates at a time and the total is always 200000.

